    create(:employment, company:, user:)
    user.add_role("owner", company)
    project = create(:project, client: create(:client, company:))
    entry = Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current,
      duration: 60.0, note: "before", bill_status: TimesheetEntry.bill_statuses.keys.find { |s| s != "billed" }
    )
    sql_count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    injected = Class.new(StandardError)
    failing_checkpoint = ->(step) { raise injected if step.to_s == "entry_written" }

    expect(described_class::STEPS.map(&:to_s)).to include("entry_written")
