RSpec.describe Timekeeping::LocalOwner do
  # "An id from another company answers `not_found`, in the same shape as a missing id."
  it "local owner answers another company's entry exactly like a missing id and changes nothing" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company_a = create(:company)
    company_b = create(:company)
    owner_a = create(:user)
    create(:employment, company: company_a, user: owner_a)
    owner_a.add_role("owner", company_a)
    owner_b = create(:user)
    create(:employment, company: company_b, user: owner_b)
    owner_b.add_role("owner", company_b)
    project_a = create(:project, client: create(:client, company: company_a))
    entry_a = Timekeeping::LocalEntry.create!(
      company_id: company_a.id, user_id: owner_a.id, project_id: project_a.id, work_date: Date.current,
      duration: 60.0, note: "company a", bill_status: TimesheetEntry.bill_statuses.keys.find { |s| s != "billed" }
    )
    update_from_b = lambda do |entry_id, key|
      described_class.call(operation: :update, company_id: company_b.id, generation: generation.to_s,
                           actor: described_class::Actor.user(user_id: owner_b.id, role: "owner"),
                           params: { "idempotency_key" => key, "entry_id" => entry_id,
                                     "body" => { "note" => "taken over", "company_id" => company_a.id } })
    end

    foreign = update_from_b.call(entry_a.id, "foreign-key")
    missing = update_from_b.call(entry_a.id + 1_000_000, "missing-key")

    expect(foreign.status).to eq(404)
    expect(foreign.status).to eq(missing.status)
    expect(foreign.body).to eq(missing.body)
    entry_a.reload
    expect(entry_a.note).to eq("company a")
    expect(entry_a.version).to eq(1)
    expect(Timekeeping::LocalOutboxEntry.count).to eq(0)
  end
end


RSpec.describe Timekeeping::LocalOwner do
  # "`LocalOwner` runs it on the parsed body before any write, with held credentials `TIMEKEEPING_SERVICE_TOKEN` and the public half of `TIMEKEEPING_TOKEN_PRIVATE_KEY`, and answers `credential_in_body`."
  it "local owner answers credential_in_body for a nested service token and stores nothing" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("owner", company)
    project = create(:project, client: create(:client, company:))
    held_token = "held-service-token-#{SecureRandom.hex(16)}"
    previous = ENV["TIMEKEEPING_SERVICE_TOKEN"]
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = held_token

    begin
      outcome = described_class.call(
        operation: :create, company_id: company.id, generation: generation.to_s,
        actor: described_class::Actor.user(user_id: user.id, role: "owner"),
        params: { "idempotency_key" => "credential-key",
                  "body" => { "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => 5.0,
                              "note" => "harmless", "source" => TimesheetEntry::SOURCES.first,
                              "source_metadata" => { "outer" => { "inner" => ["x", held_token] } } } }
      )
    ensure
      ENV["TIMEKEEPING_SERVICE_TOKEN"] = previous
    end

    expect(outcome.body.with_indifferent_access[:reason].to_s).to eq("credential_in_body")
    expect(outcome.body.to_json).not_to include(held_token)
    expect(Timekeeping::LocalEntry.count).to eq(0)
    expect(ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM entry_audits").to_i).to eq(0)
    expect(ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM idempotency_records").to_i).to eq(0)
    expect(Timekeeping::LocalOutboxEntry.count).to eq(0)
  end
end


RSpec.describe Timekeeping::LocalOwner do
  # "`locked` is true when any reservation row, provisional or committed, exists for the entry in the same company."
  it "local owner outbox payload takes locked from reservations, never from entries.locked" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("owner", company)
    project = create(:project, client: create(:client, company:))
    unbilled = TimesheetEntry.bill_statuses.keys.find { |s| s != "billed" }
    reserved = Timekeeping::LocalEntry.create!(company_id: company.id, user_id: user.id, project_id: project.id,
                                               work_date: Date.current, duration: 1.1, bill_status: unbilled, locked: false)
    flagged = Timekeeping::LocalEntry.create!(company_id: company.id, user_id: user.id, project_id: project.id,
                                              work_date: Date.current, duration: 0.1 + 0.2, bill_status: unbilled, locked: true)
    ActiveRecord::Base.connection.execute(ActiveRecord::Base.sanitize_sql_array([
      "INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at) " \
      "VALUES (?, ?, 1, gen_random_uuid(), 'provisional', 'active', now())", company.id, reserved.id
    ]))
    update = lambda do |entry, key|
      described_class.call(operation: :update, company_id: company.id, generation: generation.to_s,
                           actor: described_class::Actor.user(user_id: user.id, role: "owner"),
                           params: { "idempotency_key" => key, "entry_id" => entry.id, "body" => { "note" => "touched" } })
    end

    expect(update.call(reserved, "locked-1").status).to eq(200)
    expect(update.call(flagged, "locked-2").status).to eq(200)

    reserved_payload = Timekeeping::LocalOutboxEntry.find_by!(company_id: company.id, entry_id: reserved.id).payload
    flagged_payload = Timekeeping::LocalOutboxEntry.find_by!(company_id: company.id, entry_id: flagged.id).payload
    expect(reserved_payload["locked"]).to be(true)
    expect(flagged_payload["locked"]).to be(false)
    expect(reserved_payload.keys.sort).to eq(Timekeeping::SnapshotBatch::ENTRY_FIELDS.sort)
    expect(reserved_payload["duration"]).to eq(1.1)
    expect(flagged_payload["duration"]).to eq(0.1 + 0.2)
    expect(Time.iso8601(reserved_payload["updated_at"])).to eq(reserved.reload.updated_at)
  end
end


RSpec.describe Timekeeping::LocalOwner do
  # "Refuse `source` and `bill_status` values that `Timekeeping::SnapshotBatch` would refuse, with 400, so no snapshot can stall the relay."
  it "local owner refuses a source SnapshotBatch would refuse with 400 and still deletes on an empty body" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("owner", company)
    project = create(:project, client: create(:client, company:))
    actor = described_class::Actor.user(user_id: user.id, role: "owner")
    bad_source = "#{TimesheetEntry::SOURCES.join}-unknown"
    bad_bill_status = "#{TimesheetEntry.bill_statuses.keys.join}-unknown"
    base_body = { "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => 12.0,
                  "note" => "x", "source" => TimesheetEntry::SOURCES.first, "source_metadata" => {} }

    bad_source_outcome = described_class.call(operation: :create, company_id: company.id, generation: generation.to_s,
                                              actor:, params: { "idempotency_key" => "bad-source",
                                                                "body" => base_body.merge("source" => bad_source) })
    bad_status_outcome = described_class.call(operation: :create, company_id: company.id, generation: generation.to_s,
                                              actor:, params: { "idempotency_key" => "bad-status",
                                                                "body" => base_body.merge("bill_status" => bad_bill_status) })
    expect(bad_source_outcome.status).to eq(400)
    expect(bad_status_outcome.status).to eq(400)
    expect(Timekeeping::LocalEntry.count).to eq(0)
    expect(Timekeeping::LocalOutboxEntry.count).to eq(0)

    entry = Timekeeping::LocalEntry.create!(company_id: company.id, user_id: user.id, project_id: project.id,
                                            work_date: Date.current, duration: 3.0,
                                            bill_status: TimesheetEntry.bill_statuses.keys.find { |s| s != "billed" })
    deleted = described_class.call(operation: :destroy, company_id: company.id, generation: generation.to_s, actor:,
                                   params: { "idempotency_key" => "empty-delete", "entry_id" => entry.id, "body" => {} })
    expect(deleted.status).to eq(200)
    expect(entry.reload.discarded_at).not_to be_nil
    expect(Timekeeping::LocalOutboxEntry.where(company_id: company.id, entry_id: entry.id).count).to eq(1)
  end
end


